import type {
  ItemsApiGetItemsRequest,
  ItemsApiGetResumeItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
  UserLibraryApiGetLatestMediaRequest,
} from "@jellyfin/sdk/lib/generated-client";
import { Effect } from "effect";
import { HttpError, NoEpisodeFound } from "../../../error";
import { JellyfinService, JellyfinServiceLayer } from "../service";
import { mapLibrary, mapMediaItem, mapTrackSummary } from "./mapper";
import type { Library, MediaItem, PlaybackMetadata, PlaybackSource } from "./types";

const isNotFound = (error: unknown) =>
  error instanceof HttpError && error.status === 404;

const emptyOnNotFound = <A, E, R>(effect: Effect.Effect<A[], E, R>) =>
  effect.pipe(
    Effect.catchIf(isNotFound, () => Effect.succeed([] as A[])),
  );

const asRecord = (value: unknown): Record<string, unknown> =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : {};

const asArray = (value: unknown): unknown[] => (Array.isArray(value) ? value : []);

const mapPlaybackSource = (source: unknown): PlaybackSource => {
  const record = asRecord(source);
  return {
    id: record.Id as string | undefined,
    path: record.Path as string | undefined,
    container: record.Container as string | undefined,
    bitrate: record.Bitrate as number | undefined,
    runtimeTicks: record.RunTimeTicks as number | undefined,
  };
};

const mapPlaybackMetadata = (itemId: string, playbackInfo: unknown): PlaybackMetadata => {
  const record = asRecord(playbackInfo);
  const sources = asArray(record.MediaSources);
  const streams = sources.flatMap((source) => asArray(asRecord(source).MediaStreams));

  return {
    itemId,
    sources: sources.map(mapPlaybackSource),
    chapters: asArray(record.Chapters).map((chapter) => {
      const chapterRecord = asRecord(chapter);
      return {
        name: chapterRecord.Name as string | undefined,
        startPositionTicks: chapterRecord.StartPositionTicks as number | undefined,
      };
    }),
    trackSummary: mapTrackSummary({ MediaStreams: streams } as never),
  };
};

export class JellyfinCatalogueService extends Effect.Service<JellyfinCatalogueService>()(
  "JellyfinCatalogueService",
  {
    dependencies: [JellyfinServiceLayer],
    effect: Effect.gen(function* () {
      const jellyfin = yield* JellyfinService;

      const libraries = (): Effect.Effect<Library[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLibraries().pipe(
            Effect.map((items) => items.map((item) => mapLibrary(item))),
          ),
        );

      const itemById = (id: string, params?: ItemsApiGetItemsRequest) =>
        jellyfin.getItem(id, params).pipe(Effect.map((item) => mapMediaItem(item)));

      const items = (params?: ItemsApiGetItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const resumeRail = (params?: ItemsApiGetResumeItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getResumeItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const nextUpRail = (params?: ItemsApiGetResumeItemsRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getNextupItems(params).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const latestMovieRail = (params?: UserLibraryApiGetLatestMediaRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLatestMedia({ includeItemTypes: ["Movie"], ...params }).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const latestTvRail = (params?: UserLibraryApiGetLatestMediaRequest): Effect.Effect<MediaItem[], unknown> =>
        emptyOnNotFound(
          jellyfin.getLatestMedia({ includeItemTypes: ["Series", "Episode"], ...params }).pipe(
            Effect.map((results) => results.map((item) => mapMediaItem(item))),
          ),
        );

      const nextEpisode = (item: MediaItem) =>
        Effect.gen(function* () {
          if (!item.indexNumber) {
            return yield* new NoEpisodeFound();
          }

          const episodes = yield* items({
            parentId: item.parentId,
            fields: ["ParentId", "MediaStreams"],
            enableUserData: true,
            includeItemTypes: ["Episode"],
            sortBy: ["IndexNumber"],
            sortOrder: ["Ascending"],
            enableImages: true,
          });

          const next = episodes.reduce<MediaItem | undefined>((best, candidate) => {
            if (typeof candidate.indexNumber !== "number" || candidate.indexNumber <= item.indexNumber!) {
              return best;
            }
            if (!best || typeof best.indexNumber !== "number" || candidate.indexNumber < best.indexNumber) {
              return candidate;
            }
            return best;
          }, undefined);

          if (!next) {
            return yield* new NoEpisodeFound();
          }

          return next;
        });

      const playbackMetadata = (id: string, params?: MediaInfoApiGetPlaybackInfoRequest) =>
        jellyfin.getPlaybackState(id, params).pipe(
          Effect.map((playbackInfo) => mapPlaybackMetadata(id, playbackInfo)),
        );

      return {
        libraries,
        itemById,
        items,
        resumeRail,
        nextUpRail,
        latestMovieRail,
        latestTvRail,
        nextEpisode,
        playbackMetadata,
        markItemPlayed: jellyfin.markItemPlayed,
        markItemUnPlayed: jellyfin.markItemUnPlayed,
        markItemFavorite: jellyfin.markItemFavorite,
        markItemUnFavorite: jellyfin.markItemUnFavorite,
      };
    }),
  },
) {}

export const JellyfinCatalogueServiceLayer = JellyfinCatalogueService.Default;

import type {
  BaseItemDto,
  ItemsApiGetItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { SolidQueryOptions } from "@tanstack/solid-query";
import { Effect, pipe } from "effect";
import type { Accessor } from "solid-js";
import { HttpError } from "~/effect/error";
import {
  createEffectMutation,
  createEffectQuery,
  createQueryDataHelpers,
  createQueryKey,
  type ExtractQueryData,
} from "~/effect/tanstack/query";
import { safeAssign } from "~/lib/utils";
import { JellyfinService, type WithImage } from "./service";

const LIBRARIES_TIMEOUT = "10 seconds";

class Jellyfin {
  librariesQueryKey = createQueryKey("getLibraries");
  librariesQueryDataHelpers = createQueryDataHelpers(this.librariesQueryKey);
  getLibraries = () =>
    createEffectQuery(() => ({
      queryKey: this.librariesQueryKey(),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) => jf.getLibraries()),
          Effect.timeoutFail({
            duration: LIBRARIES_TIMEOUT,
            onTimeout: () =>
              new HttpError({
                status: 408,
                message:
                  "Loading libraries from Jellyfin timed out. Please try again.",
              }),
          })
        ),
    }));

  resumeItemsQueryKey = createQueryKey("getResumeItems");
  resumeItemsQueryDataHelpers = createQueryDataHelpers(
    this.resumeItemsQueryKey
  );
  getResumeItems = () =>
    createEffectQuery(() => ({
      queryKey: this.resumeItemsQueryKey(),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) => jf.getResumeItems()),
          Effect.catchTag("HttpError", (e) => {
            if (e.status === 404) {
              return Effect.succeed([]);
            }
            return Effect.fail(e);
          })
        ),
    }));

  nextupItemsQueryKey = createQueryKey("getNextupItems");
  nextupItemsQueryDataHelpers = createQueryDataHelpers(
    this.resumeItemsQueryKey
  );
  getNextupItems = () =>
    createEffectQuery(() => ({
      queryKey: this.nextupItemsQueryKey(),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) => jf.getNextupItems({ limit: 4 }))
        ),
    }));

  latestMoviesQueryKey = createQueryKey<"getLatestMovies", { search: string }>(
    "getLatestMovies"
  );
  latestMoviesQueryDataHelpers = createQueryDataHelpers(
    this.latestMoviesQueryKey
  );
  getLatestMovies = (
    searchTerm: () => string,
    libraries: BaseItemDto[] | undefined
  ) =>
    createEffectQuery(() => ({
      queryKey: this.latestMoviesQueryKey({ search: searchTerm() }),
      queryFn: () =>
        Effect.if(Boolean(searchTerm()), {
          onTrue: () =>
            JellyfinService.pipe(
              Effect.bind("parentId", () => {
                const parentIds =
                  libraries
                    ?.filter((library) => library.CollectionType === "movies")
                    ?.map((library) => library.Id)
                    .filter((id) => id !== undefined) ?? [];

                return Effect.succeed(parentIds[0]);
              }),
              Effect.flatMap((jf) =>
                jf.getItems({
                  parentId: jf.parentId,
                  enableImages: true,
                  fields: ["ParentId"],
                  includeItemTypes: ["Movie"],
                  limit: 7,
                  recursive: true,
                  searchTerm: searchTerm(),
                })
              ),
              Effect.catchTag("HttpError", (e) => {
                if (e.status === 404) {
                  return Effect.succeed([]);
                }

                return Effect.fail(e);
              })
            ),
          onFalse: () =>
            JellyfinService.pipe(
              Effect.flatMap((jf) =>
                jf.getLatestMedia({
                  limit: 7,
                  includeItemTypes: ["Movie"],
                })
              )
            ),
        }),
      enabled: libraries?.some(
        (library) => library.CollectionType === "movies"
      ),
    }));

  latestTVShowsQueryKey = createQueryKey<
    "getLatestTVShows",
    { search: string }
  >("getLatestTVShows");
  latestTVShowsQueryDataHelpers = createQueryDataHelpers(
    this.latestTVShowsQueryKey
  );
  getLatestTVShows = (
    searchTerm: () => string,
    libraries: BaseItemDto[] | undefined
  ) =>
    createEffectQuery(() => ({
      queryKey: this.latestTVShowsQueryKey({ search: searchTerm() }),
      queryFn: () =>
        Effect.if(Boolean(searchTerm()), {
          onTrue: () =>
            JellyfinService.pipe(
              Effect.bind("parentId", () => {
                const parentIds =
                  libraries
                    ?.filter((library) => library.CollectionType === "tvshows")
                    ?.map((library) => library.Id)
                    .filter((id) => id !== undefined) ?? [];

                return Effect.succeed(parentIds[0]);
              }),
              Effect.flatMap((jf) =>
                jf.getItems({
                  parentId: jf.parentId,
                  enableImages: true,
                  fields: ["ParentId"],
                  includeItemTypes: ["Series"],
                  limit: 7,
                  recursive: true,
                  searchTerm: searchTerm(),
                })
              ),
              Effect.catchTag("HttpError", (e) => {
                if (e.status === 404) {
                  return Effect.succeed([]);
                }

                return Effect.fail(e);
              })
            ),
          onFalse: () =>
            JellyfinService.pipe(
              Effect.flatMap((jf) =>
                jf.getLatestMedia({
                  limit: 7,
                  includeItemTypes: ["Series"],
                })
              )
            ),
        }),
      enabled: libraries?.some(
        (library) => library.CollectionType === "tvshows"
      ),
    }));

  itemQueryKey = createQueryKey<"getItem", { id: string }>("getItem");

  itemQueryDataHelpers = createQueryDataHelpers<
    ExtractQueryData<ReturnType<typeof this.getItem>>,
    { id: string }
  >(this.itemQueryKey);

  getItem = (
    id: () => string,
    params?: ItemsApiGetItemsRequest,
    queryOptions?: Accessor<
      Omit<
        SolidQueryOptions<
          Effect.Effect.Success<ReturnType<JellyfinService["getItem"]>>, // TQueryFnData
          Effect.Effect.Error<ReturnType<JellyfinService["getItem"]>>, // TError
          Effect.Effect.Success<ReturnType<JellyfinService["getItem"]>>, // TQueryFnData
          ReturnType<typeof this.itemQueryKey> // TQueryKey
        >,
        "queryFn" | "queryKey"
      >
    >
  ) =>
    createEffectQuery(() => ({
      queryKey: this.itemQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) =>
            jf.getItem(id(), {
              enableImages: true,
              ...params,
            })
          )
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  itemsQueryKey = createQueryKey<
    "getItems",
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >("getItems");
  itemsQueryDataHelpers = createQueryDataHelpers(this.itemsQueryKey);

  getItems = (
    params?:
      | ItemsApiGetItemsRequest
      | Accessor<ItemsApiGetItemsRequest | undefined>
  ) =>
    createEffectQuery(() => {
      const request = typeof params === "function" ? params() : params;

      return {
        queryKey: this.itemsQueryKey({
          parentId: request?.parentId,
          ids: request?.ids,
          searchTerm: request?.searchTerm,
        }),
        queryFn: () =>
          JellyfinService.pipe(
            Effect.flatMap((jf) =>
              jf.getItems({
                enableImages: true,
                ...request,
              })
            )
          ),
      };
    });

  getNextEpisode = (item: () => WithImage<BaseItemDto> | undefined) =>
    createEffectQuery(() => ({
      queryKey: ["getNextEpisode", { id: item()?.Id }],
      queryFn: () =>
        pipe(
          Effect.fromNullable(item()),
          Effect.flatMap((i) =>
            JellyfinService.pipe(Effect.flatMap((jf) => jf.getNextEpisode(i)))
          )
        ),
      enabled: () => Boolean(item()?.Id),
    }));

  playstateKey = createQueryKey<"getPlaystate", { id: string }>("getPlaystate");

  playstateDataHelpers = createQueryDataHelpers<
    ExtractQueryData<ReturnType<typeof this.getItem>>,
    { id: string }
  >(this.playstateKey);

  getPlaystate = (
    id: () => string,
    params?: MediaInfoApiGetPlaybackInfoRequest,
    queryOptions?: Accessor<
      Omit<
        SolidQueryOptions<
          Effect.Effect.Success<
            ReturnType<JellyfinService["getPlaybackState"]>
          >, // TQueryFnData
          Effect.Effect.Error<ReturnType<JellyfinService["getPlaybackState"]>>, // TError
          Effect.Effect.Success<
            ReturnType<JellyfinService["getPlaybackState"]>
          >, // TQueryFnData
          ReturnType<typeof this.playstateKey> // TQueryKey
        >,
        "queryFn" | "queryKey"
      >
    >
  ) =>
    createEffectQuery(() => ({
      queryKey: this.playstateKey({ id: id() }),
      queryFn: () =>
        JellyfinService.pipe(
          Effect.flatMap((jf) => jf.getPlaybackState(id(), params))
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  /*
   *
   *
   * Mutations
   *
   *
   */
  markItemPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["markItemPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: Jellyfin) {
            this.itemQueryDataHelpers.cancelQuery({ id });

            const service = yield* JellyfinService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            // Optimistic update
            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "UserData", {
                Played: true,
                LastPlayedDate: new Date().toISOString(),
              });
            });

            yield* service.markItemPlayed(id).pipe(
              Effect.catchTag("MutationError", (e) => {
                if (!prevData) {
                  return Effect.fail(e);
                }
                this.itemQueryDataHelpers.setData({ id }, prevData);
                return Effect.fail(e);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });

              if (onDone) {
                await onDone();
              }
            });
          }.bind(this)
        ),
    }));

  markItemUnPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["markItemUnPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: Jellyfin) {
            this.itemQueryDataHelpers.cancelQuery({ id });

            const service = yield* JellyfinService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            // Optimistic update
            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "UserData", {
                Played: false,
                PlaybackPositionTicks: 0,
              });
            });

            yield* service.markItemUnPlayed(id).pipe(
              Effect.catchTag("MutationError", (e) => {
                if (!prevData) {
                  return Effect.fail(e);
                }
                this.itemQueryDataHelpers.setData({ id }, prevData);
                return Effect.fail(e);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              if (onDone) {
                await onDone();
              }
            });
          }.bind(this)
        ),
    }));

  markItemFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["markItemFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: Jellyfin) {
            this.itemQueryDataHelpers.cancelQuery({ id });

            const service = yield* JellyfinService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            // Optimistic update
            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "UserData", { IsFavorite: true });
            });

            yield* service.markItemFavorite(id).pipe(
              Effect.catchTag("MutationError", (e) => {
                if (!prevData) {
                  return Effect.fail(e);
                }
                this.itemQueryDataHelpers.setData({ id }, prevData);
                return Effect.fail(e);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              if (onDone) {
                await onDone();
              }
            });
          }.bind(this)
        ),
    }));

  markItemUnFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["markItemUnFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: Jellyfin) {
            this.itemQueryDataHelpers.cancelQuery({ id });

            const service = yield* JellyfinService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            // Optimistic update
            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "UserData", { IsFavorite: false });
            });

            yield* service.markItemUnFavorite(id).pipe(
              Effect.catchTag("MutationError", (e) => {
                if (!prevData) {
                  return Effect.fail(e);
                }
                this.itemQueryDataHelpers.setData({ id }, prevData);
                return Effect.fail(e);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              if (onDone) {
                await onDone();
              }
            });
          }.bind(this)
        ),
    }));
}

export type JellyfinOperationsType = Jellyfin;

export const JellyfinOperations = new Jellyfin();

import {
  type InitialDataFunction,
  type MutationFunction,
  QueryClient,
  type QueryFunction,
  type QueryFunctionContext,
  type SolidMutationOptions,
  type SolidQueryOptions,
  type skipToken,
  type UseMutationResult,
  type UseQueryResult,
  useMutation,
  useQuery,
} from "@tanstack/solid-query";
import { Effect } from "effect";
import { create, type Draft } from "mutative";
import type { Accessor } from "solid-js";
import type { RuntimeContext } from "~/effect/runtime/runtime-context";
import { useRuntime } from "~/effect/runtime/use-runtime";

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: false,
    },
  },
});

/*
 *
 *
 *
 *
 * Query Helpers
 *
 *
 *
 *
 */

/**
 * @internal
 */
const createRunner = () => {
  const runtime = useRuntime();
  return <A, E, R extends RuntimeContext>(span: string) =>
    (effect: Effect.Effect<A, E, R>): Promise<A> =>
      effect.pipe(
        Effect.withSpan(span),
        Effect.tapErrorCause(Effect.logError),
        runtime.runPromise
      );
};

export type ExtractQueryData<T> = T extends UseQueryResult<infer D, unknown>
  ? D
  : never;

type QueryKey = readonly [string, Record<string, unknown>?];
type DeepMutable<T> = {
  -readonly [P in keyof T]: T[P] extends object ? DeepMutable<T[P]> : T[P];
};

type DeepRemoveUndefined<T> = T extends Record<string, unknown>
  ? {
      [K in keyof T]: T[K] extends undefined
        ? never
        : T[K] extends Record<string, unknown>
          ? DeepRemoveUndefined<T[K]>
          : T[K] extends (infer U)[]
            ? DeepRemoveUndefined<U>[]
            : Exclude<T[K], undefined>;
    }
  : Exclude<T, undefined>;

// Remove keys that have never type
type OmitNever<T> = {
  [K in keyof T as T[K] extends never ? never : K]: T[K];
};

export type DeepClean<T> = OmitNever<DeepRemoveUndefined<T>>;

export type QueryDataUpdater<TData> = (
  draft: Draft<DeepMutable<TData>>
) => void;

type QueryKeyType<
  TKey extends string,
  TVariables = void,
> = TVariables extends void ? readonly [TKey] : readonly [TKey, TVariables];

/**
 * Creates a type-safe query key factory that can be used with or without variables
 * @template TKey The string literal type for the query key
 * @template TVariables Optional variables type. If not provided, the factory will not accept variables
 * @param key The query key string
 * @returns A function that creates a query key tuple
 *
 * @example Without variables:
 * ```typescript
 * const userKey = createQueryKey("user");
 * const key = userKey(); // returns ["user"]
 * ```
 *
 * @example With variables:
 * ```typescript
 * type UserVars = { id: string };
 * const userKey = createQueryKey<"user", UserVars>("user");
 * const key = userKey({ id: "123" }); // returns ["user", { id: "123" }]
 * ```
 */
export function createQueryKey<TKey extends string, TVariables = void>(
  key: TKey
) {
  return ((variables?: TVariables) =>
    variables === undefined
      ? ([key] as const)
      : ([key, variables] as const)) as TVariables extends void
    ? () => QueryKeyType<TKey>
    : (variables: TVariables) => QueryKeyType<TKey, TVariables>;
}

type QueryDataHelpers<TData, TVariables> = {
  cancelQuery: (variables: TVariables) => void;
  removeQuery: (variables: TVariables) => void;
  removeAllQueries: (variables?: TVariables) => void;
  getData: (variables: TVariables) => TData | undefined;
  setData: (
    variables: TVariables,
    updater: QueryDataUpdater<TData> | TData
  ) => TData | undefined;
  invalidateQuery: (variables: TVariables) => Promise<void>;
  invalidateAllQueries: (variables?: TVariables) => Promise<void>;
  refetchQuery: (variables: TVariables) => Promise<void>;
  refetchAllQueries: () => Promise<void>;
};
/**
 * Creates a set of helpers to manage query data in the cache
 * @template TData The type of data stored in the query
 * @template TVariables Automatically inferred from the queryKey function parameter
 * @param queryKey A function that creates a query key tuple from variables
 * @returns An object with methods to remove, update, invalidate, and invalidate all query data
 *
 * @example Without variables:
 * ```typescript
 * const userKey = createQueryKey("user");
 * type User = { name: string };
 *
 * // Types are inferred from userKey
 * const helpers = createQueryDataHelpers<User>(userKey);
 * helpers.setData(undefined, (draft) => {
 *   draft.name = "New Name";
 * });
 * ```
 *
 * @example With variables and explicit types:
 * ```typescript
 * type UserVars = { id: string };
 * type User = { id: string; name: string };
 *
 * const userKey = createQueryKey<"user", UserVars>("user");
 * const helpers = createQueryDataHelpers<User, UserVars>(userKey);
 *
 * helpers.setData({ id: "123" }, (draft) => {
 *   draft.name = "New Name";
 * });
 *
 * // Other helper methods
 * await helpers.invalidateQuery({ id: "123" });
 * await helpers.refetchQuery({ id: "123" });
 * helpers.removeQuery({ id: "123" });
 * ```
 */
export function createQueryDataHelpers<TData, TVariables = void>(
  queryKey: (variables: TVariables) => readonly [string, ...unknown[]]
): QueryDataHelpers<TData, TVariables> {
  const [namespaceKey] = queryKey(undefined as TVariables);

  return {
    cancelQuery: (variables: TVariables) => {
      queryClient.cancelQueries({ queryKey: queryKey(variables) });
    },
    removeQuery: (variables: TVariables) => {
      queryClient.removeQueries({ queryKey: queryKey(variables) });
    },
    removeAllQueries: (variables) => {
      const queryKey: QueryKey = [namespaceKey];
      if (variables) {
        queryKey.concat(variables);
      }
      queryClient.removeQueries({ queryKey, exact: false });
    },
    getData: (variables: TVariables) =>
      queryClient.getQueryData(queryKey(variables)),
    setData: (
      variables: TVariables,
      updater: QueryDataUpdater<TData> | TData
    ) =>
      queryClient.setQueryData<TData>(queryKey(variables), (oldData) => {
        if (oldData === undefined) {
          return oldData;
        }
        if (typeof updater !== "function") {
          return updater;
        }
        return create(oldData as TData, (data) => {
          (updater as QueryDataUpdater<TData>)(data);
        });
      }),
    invalidateQuery: (variables: TVariables) =>
      queryClient.invalidateQueries({ queryKey: queryKey(variables) }),
    invalidateAllQueries: (variables) => {
      const queryKey: QueryKey = [namespaceKey];
      if (variables) {
        queryKey.concat(variables);
      }
      return queryClient.invalidateQueries({ queryKey, exact: false });
    },
    refetchQuery: (variables: TVariables) =>
      queryClient.refetchQueries({ queryKey: queryKey(variables) }),
    refetchAllQueries: () =>
      queryClient.refetchQueries({ queryKey: [namespaceKey], exact: false }),
  };
}

